package iso.tool;
import java.io.*;import java.nio.file.*;import java.util.*;
public final class DependencyDetector { public static final class Dependency{public String name,path,status,category;public boolean required;Dependency(String n,boolean r,String k){name=n;required=r;category=k;status="missing";}}
 private static Dependency d(String n,boolean r,String k){return new Dependency(n,r,k);} public static List<Dependency> detect(){List<Dependency>a=new ArrayList<>();String[][]s={{"git","1","source"},{"python","1","runtime"},{"cmake","1","build"},{"gcc","0","compiler"},{"g++","0","compiler"},{"cl","0","compiler"},{"clang","0","compiler"},{"lld","0","linker"},{"nasm","0","assembler"},{"ml","0","assembler"},{"ninja","0","build"},{"msbuild","0","build"},{"xorriso","0","image"},{"oscdimg","0","image"},{"qemu-system-x86_64","0","verification"},{"java","0","runtime"},{"javac","0","compiler"},{"dotnet","0","runtime"},{"node","0","runtime"},{"go","0","compiler"},{"rustc","0","compiler"},{"7z","0","archive"}};for(String[]x:s){Dependency z=d(x[0],"1".equals(x[1]),x[2]);try{Process p=new ProcessBuilder(x[0],"--version").redirectErrorStream(true).start();z.status="found";z.path=x[0];p.destroy();}catch(Exception ignored){}a.add(z);}return a;}
 public static void write(Path f)throws IOException{Files.createDirectories(f.getParent());StringBuilder s=new StringBuilder("{\"dependencies\":[");List<Dependency>a=detect();for(int i=0;i<a.size();i++){if(i>0)s.append(',');Dependency d=a.get(i);s.append("{\"name\":\"").append(d.name).append("\",\"required\":").append(d.required).append(",\"category\":\"").append(d.category).append("\",\"status\":\"").append(d.status).append("\",\"path\":\"").append(d.path==null?"":d.path).append("\"}");}s.append("]}");Files.write(f,s.toString().getBytes("UTF-8"));}}
